<template><div class="space-y-4"><el-upload drag accept=".zip" :auto-upload="false" :on-change="load"><div>选择 ZIP 文件</div></el-upload><el-table v-if="entries.length" :data="entries" size="small"><el-table-column prop="name" label="文件名"/><el-table-column prop="size" label="大小"/></el-table><el-button v-if="entries.length" type="primary" size="small" @click="downloadAll">下载全部文件</el-button></div></template>
<script setup lang="ts">import { ref } from 'vue';import JSZip from 'jszip';import { ElMessage } from 'element-plus';const zip=ref<JSZip>();const entries=ref<any[]>([]);const load=async(f:any)=>{try{zip.value=await JSZip.loadAsync(f.raw);entries.value=Object.values(zip.value.files).filter((x:any)=>!x.dir).map((x:any)=>({name:x.name,size:'待解压'}))}catch{ElMessage.error('ZIP 文件读取失败')}};const downloadAll=async()=>{if(!zip.value)return;for(const file of Object.values(zip.value.files)){if((file as any).dir)continue;const blob=await (file as any).async('blob');const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=(file as any).name.split('/').pop();a.click()}}</script>
